        const row = payload.new;
        if (!row || !row.build_id) return;
        if (row.user_id === uid) return;
        let prof = null;
        try {
          const { data } = await supabase.from("profiles").select("id, full_name, handle, avatar_url").eq("id", row.user_id).single();
          prof = data;
        } catch (e) { /* non-fatal */ }
