    let pending;
    // Functional setState returns the previous value when nothing
    // changed; React then skips the re-render. Avoids re-render churn
    // when focus shuffles between editable elements (every input swap
    // would otherwise re-render Trailhead twice).
    const recheck = () => {
      const next = isEditableTarget(document.activeElement);
      setKeyboardOpen(prev => prev === next ? prev : next);
    };
    const onFocusIn = () => { clearTimeout(pending); recheck(); };
    // focusout fires before the new element gets focus; defer the check
    // so a tap-between-two-fields doesn't briefly hide+reshow the nav.
    const onFocusOut = () => { clearTimeout(pending); pending = setTimeout(recheck, 120); };
