      // and the feed card resolves the live route from the plan.
      routeData: trip.route_data || null,
      tripStats: {
        distance_mi: trip.distance_mi,
        elev_gain_ft: trip.elev_gain_ft,
        max_elev_ft: trip.max_elev_ft,
        duration_min: trip.duration_min,
      },
      region: (geo && geo.region) || trip.region || null,
      state_code: (geo && geo.stateCode) || trip.state_code || null,
