  const [showSatellite, setShowSatellite] = useState(() => {
    try { return localStorage.getItem("th_show_satellite") === "1"; } catch (_) { return false; }
  });
  useEffect(() => { try { localStorage.setItem("th_show_camping", showCampingSpots ? "1" : "0"); } catch (_) {} }, [showCampingSpots]);
  useEffect(() => { try { localStorage.setItem("th_show_publands", showPublicLands ? "1" : "0"); } catch (_) {} }, [showPublicLands]);
  useEffect(() => { try { localStorage.setItem("th_show_satellite", showSatellite ? "1" : "0"); } catch (_) {} }, [showSatellite]);
  // Trip-reports overlay — always starts OFF on every load (no
