  const [showTripPlans, setShowTripPlans] = useState(() => {
    try { return localStorage.getItem("th_show_trip_plans") === "1"; } catch (_) { return false; }
  });
  useEffect(() => { try { localStorage.setItem("th_show_trip_plans", showTripPlans ? "1" : "0"); } catch (_) {} }, [showTripPlans]);
  // Build likes — persisted in public.build_likes. Mirrors the post-likes
  // pattern: counts keyed by build id, set of build ids the current user has liked.
  const [buildLikeCounts, setBuildLikeCounts] = useState({}); // { buildId: n }
  const [likedBuildIds, setLikedBuildIds] = useState({});     // { buildId: true }
  // Trip report likes — same pattern, persisted in public.trip_report_likes.
  const [tripLikeCounts, setTripLikeCounts] = useState({}); // { tripId: n }
  const [likedTripIds, setLikedTripIds] = useState({});     // { tripId: true }
  // DM message reactions — iMessage-style emoji tapbacks. One reaction per
