  const dmMessageReactionsRef = useRef(dmMessageReactions);
  useEffect(() => { dmMessageReactionsRef.current = dmMessageReactions; }, [dmMessageReactions]);
  // Real (DB-backed) builds only — used by route/post selectors that ask
